#!/usr/bin/env python3
from pwn import *

# Set up logging
context.log_level = 'debug'

try:
    # Connect to the remote server
    conn = remote('pwn.chal.csaw.io', 5000)

    # Receive initial prompt
    conn.recvuntil(b'Enter the password: ')

    # Send the password
    conn.sendline(b'password')

    # Get response with timeout
    response = conn.recv(timeout=2)
    print("Response:", response)

    # Try to receive more if available
    while True:
        try:
            more = conn.recv(timeout=1)
            if more:
                print("Additional response:", more)
            else:
                break
        except:
            break

except Exception as e:
    print("Error:", e)
finally:
    if 'conn' in locals():
        conn.close()

